# PTX source for fp16 matrix multiplication (A @ B.T) on SM 80
PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry matmul_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    // -----------------------------------------------------------------
    // Load kernel parameters
    // -----------------------------------------------------------------
    .reg .u64 %a_ptr, %b_ptr, %c_ptr;
    .reg .u32 %M, %N, %K;
    ld.param.u64 %a_ptr, [A_ptr];
    ld.param.u64 %b_ptr, [B_ptr];
    ld.param.u64 %c_ptr, [C_ptr];
    ld.param.u32 %M, [M];
    ld.param.u32 %N, [N];
    ld.param.u32 %K, [K];

    // -----------------------------------------------------------------
    // Thread / block indices
    // -----------------------------------------------------------------
    .reg .u32 %tid_x, %tid_y, %bid_x, %bid_y;
    mov.u32 %tid_x, %tid.x;
    mov.u32 %tid_y, %tid.y;
    mov.u32 %bid_x, %ctaid.x;
    mov.u32 %bid_y, %ctaid.y;

    // row = blockIdx.y * blockDim.y + threadIdx.y
    // col = blockIdx.x * blockDim.x + threadIdx.x
    .reg .u32 %row, %col;
    mad.lo.u32 %row, %bid_y, %ntid.y, %tid_y;
    mad.lo.u32 %col, %bid_x, %ntid.x, %tid_x;

    // -----------------------------------------------------------------
    // Bounds check – exit if outside the output matrix
    // -----------------------------------------------------------------
    .pred %p_out_of_bounds;
    setp.ge.u32 %p_out_of_bounds, %row, %M;
    @%p_out_of_bounds bra DONE;
    setp.ge.u32 %p_out_of_bounds, %col, %N;
    @%p_out_of_bounds bra DONE;

    // -----------------------------------------------------------------
    // Accumulator (float32 for higher precision)
    // -----------------------------------------------------------------
    .reg .f32 %sum;
    mov.f32 %sum, 0f00000000;

    // -----------------------------------------------------------------
    // Main K‑loop
    // -----------------------------------------------------------------
    .reg .u32 %k;
    mov.u32 %k, 0;
K_LOOP:
    setp.ge.u32 %p_out_of_bounds, %k, %K;
    @%p_out_of_bounds bra K_DONE;

    // ---- Load A[row, k] (half) ------------------------------------
    .reg .u32 %a_idx;
    mad.lo.u32 %a_idx, %row, %K, %k;           // row*K + k
    .reg .u64 %a_off;
    shl.b64 %a_off, %a_idx, 1;                // *2 bytes
    .reg .u64 %a_addr;
    add.u64 %a_addr, %a_ptr, %a_off;
    .reg .f16 %a_val;
    ld.global.f16 %a_val, [%a_addr];

    // ---- Load B[col, k] (half) ------------------------------------
    .reg .u32 %b_idx;
    mad.lo.u32 %b_idx, %col, %K, %k;           // col*K + k
    .reg .u64 %b_off;
    shl.b64 %b_off, %b_idx, 1;
    .reg .u64 %b_addr;
    add.u64 %b_addr, %b_ptr, %b_off;
    .reg .f16 %b_val;
    ld.global.f16 %b_val, [%b_addr];

    // ---- Convert to fp32 -------------------------------------------
    .reg .f32 %a_f, %b_f;
    cvt.rn.f32.f16 %a_f, %a_val;
    cvt.rn.f32.f16 %b_f, %b_val;

    // ---- Accumulate ------------------------------------------------
    fma.rn.f32 %sum, %a_f, %b_f, %sum;        // sum += a_f * b_f

    // ---- Increment k ------------------------------------------------
    add.u32 %k, %k, 1;
    bra K_LOOP;
K_DONE:

    // -----------------------------------------------------------------
    // Write result (convert back to half)
    // -----------------------------------------------------------------
    .reg .f16 %c_val;
    cvt.rn.f16.f32 %c_val, %sum;

    // C[row, col] = c_val
    .reg .u32 %c_idx;
    mad.lo.u32 %c_idx, %row, %N, %col;        // row*N + col
    .reg .u64 %c_off;
    shl.b64 %c_off, %c_idx, 1;
    .reg .u64 %c_addr;
    add.u64 %c_addr, %c_ptr, %c_off;
    st.global.f16 [%c_addr], %c_val;

DONE:
    ret;
}
'''

