# Python wrapper that loads and launches the PTX kernel
# ----------------------------------------------------------------------
import torch

# The harness is assumed to provide these functions:
#   ptx_load(source: str) -> module_handle
#   ptx_launch(module, kernel_name: str, grid: tuple, block: tuple, args: list)
# They are imported from the surrounding environment.

class ModelNew(torch.nn.Module):
    def __init__(self):
        super().__init__()
        # Load PTX module once
        self._module = ptx_load(PTX_SOURCE)
        self._kernel_name = "matmul_kernel"
        # Fixed block size (32 x 8 threads)
        self._block = (32, 8, 1)

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        A: (M, K)   fp16 GPU tensor
        B: (N, K)   fp16 GPU tensor (will be transposed inside the kernel)
        Returns:
            C: (M, N) fp16 GPU tensor
        """
        assert A.is_cuda and B.is_cuda
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        M, K = A.shape
        N, Kb = B.shape
        assert K == Kb, "Inner dimensions must match"

        C = torch.empty((M, N), dtype=torch.float16, device='cuda')

        # Compute launch grid
        grid_x = (N + self._block[0] - 1) // self._block[0]
        grid_y = (M + self._block[1] - 1) // self._block[1]
        grid = (grid_x, grid_y, 1)

        # Prepare arguments (all as 64‑bit ints for pointers, 32‑bit for sizes)
        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            int(M),
            int(N),
            int(K)
        ]

        # Launch kernel
        ptx_launch(self._module, self._kernel_name, grid, self._block, args)

        return C
